<template>
  <div class="listening-page">
    <!-- 背景图片容器 -->
    <div class="bg-container">
      <!-- 动态星光背景容器 -->
      <div id="stars" class="star-background">
        <!-- 动态生成的星光将插入到这里 -->
      </div>
    </div>

    <div class="player-container">
      <h2 class="page-title">六级听力练习</h2>
      <div class="audio-player">
        <!-- 音频播放控件 -->
        <audio controls class="audio-control">
          <source src="https://123.56.203.202/api/download-audio?as_attachment=false" type="audio/wav">
          你的浏览器不支持音频播放功能
        </audio>
        
        <p class="audio-info">当前播放: 2025.6 六级听力 Passage 1</p>
        
        <!-- 下载按钮 -->
        <button 
          class="download-btn" 
          @click="downloadAudio"
          :disabled="isDownloading"
        >
          <i class="fas fa-download"></i>
          {{ isDownloading ? '下载中...' : '下载音频' }}
        </button>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  data() {
    return {
      starContainer: null,
      isDownloading: false,
      audioUrl: "https://123.56.203.202/api/download-audio?as_attachment=false"
    };
  },
  mounted() {
    this.initStarAnimation();
    // 初始化时打印URL，确认是否正确
    console.log('初始化音频URL:', this.audioUrl);
  },
  beforeDestroy() {
    // 清理动态创建的元素，避免内存泄漏
    if (this.starContainer) {
      this.starContainer.innerHTML = '';
    }
  },
  methods: {
    initStarAnimation() {
      this.starContainer = document.getElementById('stars');
      if (!this.starContainer) return;

      // 生成20颗蓝色星光
      for (let j = 0; j < 20; j++) {
        const newStar = document.createElement("div");
        newStar.className = "star";
        // 随机生成初始位置
        newStar.style.top = this.randomDistance(500, -100) + 'px';
        newStar.style.left = this.randomDistance(1300, 300) + 'px';
        this.starContainer.appendChild(newStar);
      }

      // 设置星光动画延时，使运动更自然
      const stars = document.getElementsByClassName('star');
      for (let i = 0, len = stars.length; i < len; i++) {
        stars[i].style.animationDelay = (Math.random() * 9).toFixed(1) + 's';
      }
    },
    randomDistance(max, min) {
      return Math.floor(Math.random() * (max - min + 1) + min);
    },
    async downloadAudio() {
      console.log('========== 开始下载流程 ==========');
      this.isDownloading = true;
      
      try {
        console.log('准备发起请求，URL:', this.audioUrl);
        
        // 记录请求开始时间
        const startTime = performance.now();
        
        // 仅使用fetch API处理下载
        const response = await fetch(this.audioUrl, {
          method: 'GET',
          mode: 'cors',
          headers: {
            'Accept': 'audio/wav'
          },
          // 增加调试用的请求参数
          cache: 'no-store' // 禁用缓存，确保每次都是新请求
        });
        
        // 记录请求完成时间并计算耗时
        const endTime = performance.now();
        console.log(`请求完成，耗时: ${(endTime - startTime).toFixed(2)}ms`);
        console.log('响应状态码:', response.status);
        console.log('响应状态文本:', response.statusText);
        
        // 打印所有响应头
        console.log('响应头信息:');
        response.headers.forEach((value, key) => {
          console.log(`  ${key}: ${value}`);
        });
        
        // 检查响应状态
        if (!response.ok) {
          // 获取错误响应内容（如果有）
          let errorBody = '';
          try {
            errorBody = await response.text();
            console.log('错误响应内容:', errorBody);
          } catch (e) {
            console.log('无法获取错误响应内容:', e);
          }
          throw new Error(`下载失败，状态码: ${response.status}，状态文本: ${response.statusText}`);
        }
        
        // 检查响应类型
        console.log('响应类型:', response.type);
        
        // 将响应转换为Blob对象
        console.log('开始转换响应为Blob对象...');
        const blobStartTime = performance.now();
        const blob = await response.blob();
        const blobEndTime = performance.now();
        console.log(`Blob转换完成，耗时: ${(blobEndTime - blobStartTime).toFixed(2)}ms`);
        console.log('Blob类型:', blob.type);
        console.log('Blob大小:', blob.size, '字节');
        
        // 验证Blob类型是否正确
        if (!blob.type.includes('audio')) {
          console.warn('警告: 下载的文件不是音频类型，类型为:', blob.type);
        }
        
        // 创建临时URL
        const url = window.URL.createObjectURL(blob);
        console.log('创建临时URL成功:', url);
        
        // 创建下载链接并触发下载
        console.log('准备创建下载链接...');
        const link = document.createElement('a');
        link.href = url;
        link.download = '2025.6_六级听力_Passage_1.wav';
        console.log('下载文件名:', link.download);
        
        document.body.appendChild(link);
        console.log('已将链接添加到页面');
        
        // 触发点击
        link.click();
        console.log('已触发链接点击');
        
        // 清理资源
        setTimeout(() => {
          document.body.removeChild(link);
          window.URL.revokeObjectURL(url);
          console.log('已清理临时资源');
        }, 100);
        
        console.log('下载流程完成');
        alert('下载成功！');
      } catch (error) {
        console.error('下载过程出错:', error);
        // 详细打印错误对象的所有属性
        console.error('错误详情:', {
          message: error.message,
          name: error.name,
          stack: error.stack,
          status: error.status || '未知'
        });
        alert(`下载失败: ${error.message}\n请检查控制台获取更多信息`);
      } finally {
        this.isDownloading = false;
        console.log('========== 下载流程结束 ==========');
      }
    }
  }
};
</script>

<style scoped>
/* 页面基础布局 */
.listening-page {
  position: relative;
  width: 100%;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
  box-sizing: border-box;
  z-index: 1;
}

/* 背景图片容器 */
.bg-container {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  overflow: hidden;
}

/* 背景图片样式 */
.bg-container::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url('@/../public/back.jpg');
  background-color: rgba(0, 0, 0, 0.1);
  background-size: cover;
  background-position: center;
}

/* 蓝色星光背景样式 */
.star-background {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

/* 播放器容器 */
.player-container {
  width: 100%;
  max-width: 500px;
  background: rgba(255, 255, 255, 0.92);
  border-radius: 12px;
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.15);
  overflow: hidden;
  position: relative;
  z-index: 2;
  backdrop-filter: blur(5px);
  padding: 30px;
  text-align: center;
}

/* 标题样式 */
.page-title {
  font-size: 24px;
  font-weight: 600;
  color: #333;
  margin: 0 0 25px 0;
  padding-bottom: 15px;
  border-bottom: 1px solid #e3f2fd;
}

/* 音频播放器样式 */
.audio-player {
  margin-top: 20px;
}

.audio-control {
  width: 100%;
  margin-bottom: 15px;
  padding: 8px;
  border-radius: 8px;
  background-color: rgba(255, 255, 255, 0.8);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
}

.audio-info {
  color: #666;
  font-size: 15px;
  margin: 0 0 20px 0;
  padding: 10px;
  background-color: rgba(227, 242, 253, 0.5);
  border-radius: 6px;
}

/* 下载按钮样式 */
.download-btn {
  background-color: #42a5f5;
  color: white;
  border: none;
  padding: 10px 20px;
  border-radius: 6px;
  cursor: pointer;
  font-size: 16px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: all 0.3s ease;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

.download-btn:hover {
  background-color: #1976d2;
  transform: translateY(-2px);
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.15);
}

.download-btn:disabled {
  background-color: #90caf9;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

/* 蓝色星光动画样式 */
#stars {
  width: 100%;
  height: 100vh;
  margin: 0;
  overflow: hidden;
  position: fixed;
  top: 0;
  left: 0;
  z-index: 2;
}

.star {
  display: block;
  width: 1px;
  background: transparent;
  position: absolute;
  opacity: 0.8;
  animation: star-fall 4.2s linear infinite;
}

.star:after {
  content: '';
  display: block;
  border: 0px solid #fff;
  border-width: 0px 50px 1px 50px;
  border-color: transparent transparent transparent rgba(173, 216, 230, 0.5);
  box-shadow: 0 0 1px 0 rgba(173, 216, 230, 0.1);
  transform: rotate(-45deg) translate3d(1px, 3px, 0);
  transform-origin: 0% 100%;
}

@keyframes star-fall {
  0% {
    opacity: 0;
    transform: scale(0.5) translate3d(0, 0, 0);
  }

  50% {
    opacity: 1;
    transform: translate3d(-120px, 120px, 0);
  }

  100% {
    opacity: 0;
    transform: scale(1.1) translate3d(-220px, 220px, 0);
  }
}
</style>
    